	/** 
	 * jumpstart the process by instantiating2 Product
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		productId = ProductService.getProductInstance()
		.createProduct( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ProductService.getProductInstance()
				.createProduct( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.productSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Product : " + successValue.getProductId());
							  if (successValue.getProductId().equals(productId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfProductList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Product test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on product consumed")
					);
			subscriber.productSubscribe( productId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Product : " + successValue.getProductId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfProductList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on product for productId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Product. 
	 */
	protected Product read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Product" );

		Product entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Product with primary key" );
		msg.append( productId );
		
		ProductFetchOneSummary fetchOneSummary = new ProductFetchOneSummary( productId );

		try {
			entity = ProductService.getProductInstance().getProduct( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Product " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Product.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Product." );

		StringBuilder msg = new StringBuilder( "Failed to update a Product : " );        
		Product entity = read();
		UpdateProductCommand command = generateUpdateCommand();
		command.setProductId(entity.getProductId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Product." );

			// for use later on...
			productId = entity.getProductId();

			ProductService proxy = ProductService.getProductInstance();  

			proxy.updateProduct( command ).get();

			LOGGER.info( "-- Successfully saved Product - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + productId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Product.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Product." );

		Product entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Product with id " + productId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Product with id " + productId );

			throw e;
		}

		try{
			ProductService.getProductInstance().delete( new DeleteProductCommand( entity.getProductId() ) ).get();
			LOGGER.info( "-- Successfully deleted Product with id " + productId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Product with id " + productId );

			throw e;
		}
	}

	/**
	 * get all Products.
	 */
	protected List<Product> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Products:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Product : " );        
		List<Product> collection  = new ArrayList<>();

		try {
			// call the static get method on the ProductService
			collection = ProductService.getProductInstance().getAllProduct();
			assertNotNull( collection, "An Empty collection of Product was incorrectly returned.");
			
			// Now print out the values
			Product entity = null;            
			Iterator<Product> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getProductId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

